window.I18N_DICTIONARIES = {
  en: DICTIONARY_EN,
  fr: DICTIONARY_FR,
  it: DICTIONARY_IT,
  de: DICTIONARY_DE,
  es: DICTIONARY_ES,
  nl: DICTIONARY_NL,
  pt: DICTIONARY_PT
};

// Fallback lookup: if a key is queried in another language, fall back to English
window.t = function(key, params) {
  if (!key) return '';
  const dict = window.I18N_DICTIONARIES[currentLang] || DICTIONARY_EN;
  let val = dict[key] || DICTIONARY_EN[key];
  if (val === undefined) {
    console.warn('Missing i18n key:', key);
    return key;
  }
  if (params && typeof params === 'object') {
    Object.keys(params).forEach(p => {
      val = val.replace(new RegExp('\\{' + p + '\\}', 'g'), params[p]);
    });
  }
  return val;
};

window.getCurrentLanguage = function() {
  return currentLang;
};

window.setLanguage = function(langCode) {
  if (!window.I18N_LANGUAGES.some(l => l.code === langCode)) return;
  currentLang = langCode;
  try {
    localStorage.setItem(STORAGE_LANG_KEY, langCode);
  } catch (e) {
    // storage not available
  }
  document.documentElement.lang = langCode;
  // Trigger redraw event
  window.dispatchEvent(new CustomEvent('poli-language-changed', { detail: { lang: langCode } }));
};
